  ('fd063b54-2889-4ab7-b496-de59e40c9bd4', 4,
   $r4$Yea on four single-subject, ungated MI House bills that make carrying a gun easier while the concealed pistol licence stays: HB 4855 (2026-02-05, 90-13; co-sponsor too) adds 'The individual is hunting game with a bow and arrow' to the cases where the hunting act does not 'prohibit an individual from transporting a pistol or carrying a loaded pistol'; HB 4980 (2026-01-21, 60-45; co-sponsor too) lets an applicant 'apply to a county clerk in any county in this state'; HB 4284 (2026-01-14, 63-46) cuts the renewal fee from '$115.00' to '$30.00'; HB 5113 (2026-01-21, 78-27) lets an applicant re-apply 'without paying an additional fee'. These meet rung 4 'Make carrying a gun easier' (annex rule two: an easier permit; HB 4855 widens who may carry). No rung 1-3 or rung 5 act is on file. HB 4481 is gated (92-9), HB 4949 (shooting-range noise liability) is adjacent, and his 2025 words backing a school hunter-safety course are adjacent (education, not a firearms-law rung).$r4$,
   $r4$Yea on four single-subject, ungated MI House bills, all keeping the concealed pistol licence: HB 4855 (2026-02-05, 90-13; co-sponsor too) adds 'The individual is hunting game with a bow and arrow' to the cases where the hunting act does not 'prohibit an individual from transporting a pistol or carrying a loaded pistol'; HB 4980 (2026-01-21, 60-45; co-sponsor too) lets an applicant 'apply to a county clerk in any county in this state'; HB 4284 (2026-01-14, 63-46) cuts the renewal fee from '$115.00' to '$30.00'; HB 5113 (2026-01-21, 78-27) lets an applicant re-apply 'without paying an additional fee'. HB 4284 meets rung 4 'Make carrying a gun easier' (annex rule two: an easier permit). HB 4855, HB 4980 and HB 5113, since the 2026-11-12 ruling, show only which side he is on and are not rung acts. No rung 1-3 or rung 5 act is on file. HB 4481 is gated (92-9), HB 4949 (shooting-range noise liability) is adjacent, and his 2025 words backing a school hunter-safety course are adjacent (education, not a firearms-law rung).$r4$),
  ('fe167afd-f670-4f13-9fee-2aa3fd6d048e', 5,
   $r4$Senate Yea on IN HB 1296 (2022), single-subject, conference report 30-20 Senate: it repeals the licence to carry (the text cites "section 1 of this chapter (carrying a handgun without a license) (before its repeal)" and repeals IC 35-47-2-2), replacing it with a list of persons who "may not knowingly or intentionally carry a handgun"; that list is the permit-free carry rule's own eligibility line, part of the rung 5 act (annex closure C3): rung 5 "Repeal laws that require a permit or registration for a gun". Senate Yea (39-9) on IN HB 1084 (2024), single-subject, 66-26 House conference report (39-9 Senate): "A state officer who is not prohibited from possessing a handgun under state or federal law has the right to carry a handgun within the state capitol building and on the property of the state capitol complex." is a rung 4 act on the same side; furthest act gives 5. Her HB 1284 (2019) authorship is a multi-subject bill (voter-registration offices) and is not used; her vote on it is gated. Other gun findings are gated or adjacent.$r4$,
   $r4$Senate Yea on IN HB 1296 (2022), single-subject, conference report 30-20 Senate: it repeals the licence to carry (the text cites "section 1 of this chapter (carrying a handgun without a license) (before its repeal)" and repeals IC 35-47-2-2), replacing it with a list of persons who "may not knowingly or intentionally carry a handgun"; that list is the permit-free carry rule's own eligibility line, part of the rung 5 act (annex closure C3): rung 5 "Repeal laws that require a permit or registration for a gun". Senate Yea (39-9) on IN HB 1084 (2024), single-subject, 66-26 House conference report (39-9 Senate): "A state officer who is not prohibited from possessing a handgun under state or federal law has the right to carry a handgun within the state capitol building and on the property of the state capitol complex." gives a capitol carry right for state officers, which is out of scope (not a rung act); furthest act gives 5. Her HB 1284 (2019) authorship is a multi-subject bill (voter-registration offices) and is not used; her vote on it is gated. Other gun findings are gated or adjacent.$r4$);

DO $$
DECLARE n int; m int;
BEGIN
  SELECT count(*) INTO n FROM _ca0377_fix;
  IF n <> 140 THEN RAISE EXCEPTION 'pre-flight: expected 140 fix rows, found %', n; END IF;
  SELECT count(*) INTO m FROM inform.politician_context pc JOIN _ca0377_fix f ON f.politician_id = pc.politician_id
   WHERE pc.season_id = '7b3a066c-815d-43b2-a6a0-6a3029778075' AND pc.topic_id = '56125933-b82a-46c5-847b-b2e9a146b89f' AND pc.topic_revision_id = '41349e39-394a-47b9-81c6-a79f8ec60425'
     AND pc.reasoning IN (f.old_text, f.new_text);
  IF m <> 140 THEN RAISE EXCEPTION 'pre-flight: expected 140 rows holding the old or new text, found %', m; END IF;
END $$;

UPDATE inform.politician_context pc SET reasoning = f.new_text, updated_at = now()
  FROM _ca0377_fix f
 WHERE pc.politician_id = f.politician_id AND pc.season_id = '7b3a066c-815d-43b2-a6a0-6a3029778075' AND pc.topic_id = '56125933-b82a-46c5-847b-b2e9a146b89f'
   AND pc.topic_revision_id = '41349e39-394a-47b9-81c6-a79f8ec60425' AND pc.reasoning = f.old_text;

DO $$
DECLARE n int; v int;
BEGIN
  SELECT count(*) INTO n FROM inform.politician_context pc JOIN _ca0377_fix f ON f.politician_id = pc.politician_id
   WHERE pc.season_id = '7b3a066c-815d-43b2-a6a0-6a3029778075' AND pc.topic_id = '56125933-b82a-46c5-847b-b2e9a146b89f' AND pc.topic_revision_id = '41349e39-394a-47b9-81c6-a79f8ec60425' AND pc.reasoning = f.new_text;
  IF n <> 140 THEN RAISE EXCEPTION 'post-verify: expected 140 corrected rows, found %', n; END IF;
  SELECT count(*) INTO v FROM inform.politician_answers pa JOIN _ca0377_fix f ON f.politician_id = pa.politician_id
   WHERE pa.season_id = '7b3a066c-815d-43b2-a6a0-6a3029778075' AND pa.topic_id = '56125933-b82a-46c5-847b-b2e9a146b89f' AND pa.value = f.value;
  IF v <> 140 THEN RAISE EXCEPTION 'post-verify: a seat moved (expected 140 unchanged values), found % matching', v; END IF;
END $$;

DROP TABLE _ca0377_fix;
